			"OK": {"id":"OK","initial":100,"remaining":100,"holder":"h","location":"l","children":[],"history":[]},
			"BAD": {"id":"BAD","initial":100,"remaining":100,"holder":"h","location":"l","children":[],"history":[],"pendingId":"T-ghost"}
