94		if err != nil {
95			t.Fatalf("分出最后 0.001 应成功: %v", err)
96		}
97		if parent.Remaining != "0.000" {
98			t.Fatalf("分出最后 0.001 后剩余应为 0.000, got %s", parent.Remaining)
99		}
100		if parent.InitialQty != maxQtyString {
101			t.Fatalf("用尽后来源初始量仍应保留登记值: got %s want %s",
102				parent.InitialQty, maxQtyString)
103		}
104		// 分装用尽而非销毁：不应出现销毁信息。
105		if parent.Destruction != nil {
106			t.Fatalf("分装用尽不应带销毁记录: %+v", parent.Destruction)
107		}
108		if got := parent.Children; len(got) != 2 || got[0] != firstID || got[1] != lastID {
109			t.Fatalf("子样应按分装顺序记录编号: %v", got)
110		}
111		if len(parent.History) != 3 {
112			t.Fatalf("来源历史应为 登记/分装/分装 三条, got %d", len(parent.History))
113		}
114		for i, wantKind := range []string{"register", "split", "split"} {
115			if parent.History[i].Kind != wantKind {
116				t.Fatalf("来源历史顺序错误: %+v", parent.History)
117			}
118		}
119	
120		// 最后一个子样保留实际分出量，来源关系与持有人地点同样一致。
121		last, err := s.GetSample(lastID)
122		if err != nil {
123			t.Fatalf("最后子样应可查询: %v", err)
124		}
125		if last.InitialQty != "0.001" || last.Remaining != "0.001" {
126			t.Fatalf("最后子样数量错误: init=%s remaining=%s", last.InitialQty, last.Remaining)
127		}
128		if last.ParentID != parentID || last.Holder != "张三" || last.Location != "实验室A" {
129			t.Fatalf("最后子样继承关系错误: %+v", last)
130		}
131	
132		// 大整数数量落盘后重新打开仍逐位精确，子样顺序与来源关系不丢。
133		reopened, err := Open(path)
134		if err != nil {
135			t.Fatalf("reopen: %v", err)
136		}
137		rp, err := reopened.GetSample(parentID)
138		if err != nil {
139			t.Fatal(err)
140		}
141		if rp.InitialQty != maxQtyString || rp.Remaining != "0.000" ||
142			rp.Destruction != nil ||
143			len(rp.Children) != 2 || rp.Children[0] != firstID || rp.Children[1] != lastID {
144			t.Fatalf("重开后来源状态不精确: %+v", rp)
145		}
146		rc1, err := reopened.GetSample(firstID)
147		if err != nil {
148			t.Fatal(err)
149		}
150		if rc1.InitialQty != belowMaxString || rc1.Remaining != belowMaxString ||
151			rc1.ParentID != parentID || rc1.Holder != "张三" || rc1.Location != "实验室A" {
152			t.Fatalf("重开后大数量子样状态不精确: %+v", rc1)
153		}
154		rc2, err := reopened.GetSample(lastID)
155		if err != nil {
156			t.Fatal(err)
157		}
158		if rc2.InitialQty != "0.001" || rc2.Remaining != "0.001" || rc2.ParentID != parentID {
159			t.Fatalf("重开后最后子样状态错误: %+v", rc2)
160		}
161	}
